(self.webpackChunkroot=self.webpackChunkroot||[]).push([[1786,1872],{"./node_modules/.pnpm/@mdx-js+react@3.1.1_@types+react@18.3.3_react@19.2.7/node_modules/@mdx-js/react/index.js"(__unused_webpack_module,__webpack_exports__,__webpack_require__){"use strict";__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{MDXProvider:()=>MDXProvider,useMDXComponents:()=>useMDXComponents});var react=__webpack_require__("./node_modules/.pnpm/react@18.3.1/node_modules/react/index.js");const emptyComponents={},MDXContext=react.createContext(emptyComponents);function useMDXComponents(components){const contextComponents=react.useContext(MDXContext);return react.useMemo(function(){return"function"==typeof components?components(contextComponents):{...contextComponents,...components}},[contextComponents,components])}function MDXProvider(properties){let allComponents;return allComponents=properties.disableParentContext?"function"==typeof properties.components?properties.components(emptyComponents):properties.components||emptyComponents:useMDXComponents(properties.components),react.createElement(MDXContext.Provider,{value:allComponents},properties.children)}},"./stories/21.NightingaleLogoTrack/NightingaleLogoTrack.mdx"(__unused_webpack_module,__webpack_exports__,__webpack_require__){"use strict";__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{default:()=>MDXContent});__webpack_require__("./node_modules/.pnpm/react@18.3.1/node_modules/react/index.js");var jsx_runtime=__webpack_require__("./node_modules/.pnpm/react@18.3.1/node_modules/react/jsx-runtime.js"),mdx_react_shim=__webpack_require__("./node_modules/.pnpm/@storybook+addon-docs@8.6.18_@types+react@18.3.3_storybook@8.6.18_prettier@3.2.5_supports-color@8.1.1_/node_modules/@storybook/addon-docs/dist/shims/mdx-react-shim.mjs"),dist=__webpack_require__("./node_modules/.pnpm/@storybook+blocks@8.6.18_react-dom@19.2.7_react@19.2.7__react@19.2.7_storybook@8.6.18_p_8f9138463b79afe28a3a362748d078e4/node_modules/@storybook/blocks/dist/index.mjs");var nightingale_base_element=__webpack_require__("./packages/nightingale-new-core/src/nightingale-base-element.md"),README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withDimensions/README.md"),withHighlight_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withHighlight/README.md"),withManager_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withManager/README.md"),withMargin_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withMargin/README.md"),withPosition_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withPosition/README.md"),withResizable_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withResizable/README.md"),withZoom_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withZoom/README.md");function _createMdxContent(props){const _components={p:"p",...(0,mdx_react_shim.useMDXComponents)(),...props.components};return(0,jsx_runtime.jsxs)(jsx_runtime.Fragment,{children:[(0,jsx_runtime.jsx)(dist.Meta,{title:"Components/Tracks/Logo Track/Readme"}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:'# nightingale-logo-track\n\n[![Published on NPM](https://img.shields.io/npm/v/@nightingale-elements/nightingale-logo-track.svg)](https://www.npmjs.com/package/@nightingale-elements/nightingale-logo-track)\n\nThe `nightingale-logo-track` component renders a sequence logo from a multiple sequence alignment. It works with both nucleotide (RNA/DNA) and amino acid (protein) alignments — the sequence type is detected automatically from the data. Each column displays letters scaled by their information content (IC), computed as the reduction in Shannon entropy relative to the maximum possible entropy for the alphabet. Gap-heavy columns are scaled down proportionally by coverage. The most-conserved residue is rendered at the top of each stack.\n\n**Nucleotide colour scheme (RNA/DNA — up to 2 bits per column)**\n\n| Base | Colour |\n|------|--------|\n| A | Green `#00CC00` |\n| C | Blue `#0000CC` |\n| G | Amber `#FFB300` |\n| U / T | Red `#CC0000` |\n\nDNA thymine (T) is automatically treated as RNA uracil (U).\n\n**Amino acid colour scheme (protein — up to ~4.32 bits per column)**\n\nColors follow the [WebLogo](https://weblogo.threeplusone.com) chemistry grouping:\n\n| Group | Residues | Colour |\n|-------|----------|--------|\n| Hydrophobic | A G V L I P F M W | Orange `#FF8C00` |\n| Polar uncharged | S T C Y N Q | Green `#00CC00` |\n| Positively charged | K R H | Blue `#0000CC` |\n| Negatively charged | D E | Red `#CC0000` |\n\nAs `nightingale-logo-track` implements `withManager`, `withZoom`, and `withSVGHighlight`, it will respond to zoom, pan, and highlight events propagated by `nightingale-manager` and emit change events when the user hovers over, clicks, zooms or pans it.\n\n## Usage\n\n### Standalone\n\n```html\n<nightingale-logo-track\n  id="logo"\n  height="120"\n  min-width="400"\n  length="23"\n  margin-top="10"\n  margin-bottom="10"\n  use-ctrl-to-zoom\n></nightingale-logo-track>\n\n<script type="module">\n  import "@nightingale-elements/nightingale-logo-track";\n  const track = document.querySelector("#logo");\n  track.sequences = [\n    { name: "seq1", sequence: "AAAGUCGGGCUUAUGCAACCGGU" },\n    { name: "seq2", sequence: "AAACCCGGGCUUAUGCAACCGGU" },\n    // ...\n  ];\n<\/script>\n```\n\n### With `nightingale-manager`\n\nPlacing the track inside a `nightingale-manager` synchronises zoom, pan, and highlight with any other registered nightingale components (navigation, MSA, sequence, etc.).\n\n```html\n<nightingale-manager>\n  <nightingale-navigation\n    id="nav"\n    height="44"\n    length="23"\n  ></nightingale-navigation>\n\n  <nightingale-logo-track\n    id="logo"\n    height="120"\n    length="23"\n    margin-top="10"\n    margin-bottom="10"\n    highlight-event="onmouseover"\n    highlight-color="#EB3BFF22"\n    use-ctrl-to-zoom\n  ></nightingale-logo-track>\n</nightingale-manager>\n\n<script type="module">\n  import "@nightingale-elements/nightingale-manager";\n  import "@nightingale-elements/nightingale-navigation";\n  import "@nightingale-elements/nightingale-logo-track";\n\n  await customElements.whenDefined("nightingale-logo-track");\n  document.querySelector("#logo").sequences = [\n    { name: "seq1", sequence: "AAAGUCGGGCUUAUGCAACCGGU" },\n    { name: "seq2", sequence: "AAACCCGGGCUUAUGCAACCGGU" },\n    // ...\n  ];\n<\/script>\n```\n\n## API Reference\n\n### Properties\n\n#### `sequences: Array<{ name: string; sequence: string }>`\n\nGets or sets the multiple sequence alignment data. Each entry is an object with a `name` string and a `sequence` string containing single-letter residue codes. Gap characters (`-`, `.`) and unrecognised characters are ignored when computing information content.\n\nThe sequence type is detected automatically when `sequences` is set: if more than 5 % of non-gap characters are letters that only occur in proteins (`E F I L P Q`, or the rare `J O Z`), the track switches to protein mode and applies the amino acid colour scheme and a 20-letter IC ceiling. Otherwise it operates in nucleotide mode and DNA thymine is treated as uracil.\n\n```javascript\n// RNA / DNA\ntrack.sequences = [\n  { name: "seq1", sequence: "AAAGUCGGGCUUAUGCAACCGGU" },\n  { name: "seq2", sequence: "AAACCCGAGCUUAUGCAACCGGU" },\n];\n\n// Protein — type detected automatically\ntrack.sequences = [\n  { name: "prot1", sequence: "AMSMSVLKHHFDA" },\n  { name: "prot2", sequence: "AMSMSVLRHHFDA" },\n];\n```\n\n### Attributes\n\nAll standard nightingale attributes are supported.\n\n#### `height?: number`\n\nHeight of the track in pixels. Defaults to the element\'s CSS height.\n\n#### `length?: number`\n\nTotal length of the aligned sequences (number of columns).\n\n#### `display-start?: number (default: 1)`\n\nFirst sequence position to display. Managed automatically by `nightingale-manager`.\n\n#### `display-end?: number`\n\nLast sequence position to display. Managed automatically by `nightingale-manager`.\n\n#### `margin-top?: number (default: 0)`\n\nTop margin in pixels.\n\n#### `margin-bottom?: number (default: 0)`\n\nBottom margin in pixels.\n\n#### `margin-left?: number (default: 10)`\n\nLeft margin in pixels.\n\n#### `margin-right?: number (default: 10)`\n\nRight margin in pixels.\n\n#### `margin-color?: string (default: "#ffffffdd")`\n\nFill colour for the margin overlay rectangles.\n\n#### `highlight-event?: "onmouseover" | "onclick"`\n\nWhich pointer interaction on a column highlights it. The highlight is emitted in a `change` event and propagated to other components via `nightingale-manager`.\n\n#### `highlight-color?: string (default: "#FFEB3B66")`\n\nFill colour for highlighted regions.\n\n#### `use-ctrl-to-zoom?: boolean`\n\nWhen set, scrolling only zooms if Ctrl (or Cmd on macOS) is held. Without this flag, any scroll event on the track will zoom.\n\n### Other attributes and properties\n\nThis component inherits from `NightingaleElement` and implements the following mixins: `withManager`, `withSVGHighlight` (which includes `withZoom`, `withHighlight`, `withMargin`, `withPosition`, `withResizable`, `withDimensions`).\n'}),"\n",(0,jsx_runtime.jsx)("hr",{}),"\n",(0,jsx_runtime.jsx)("h2",{children:"Mixins"}),"\n",(0,jsx_runtime.jsx)("p",{children:(0,jsx_runtime.jsx)(_components.p,{children:"This component implements the following mixins, and therefore it includes\ntheir attributes and properties."})}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withHighlight_README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withManager_README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withMargin_README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withPosition_README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withResizable_README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withZoom_README}),"\n",(0,jsx_runtime.jsx)("h2",{children:"Parent Class"}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:nightingale_base_element})]})}function MDXContent(props={}){const{wrapper:MDXLayout}={...(0,mdx_react_shim.useMDXComponents)(),...props.components};return MDXLayout?(0,jsx_runtime.jsx)(MDXLayout,{...props,children:(0,jsx_runtime.jsx)(_createMdxContent,{...props})}):_createMdxContent(props)}},"./node_modules/.pnpm/@storybook+addon-docs@8.6.18_@types+react@18.3.3_storybook@8.6.18_prettier@3.2.5_supports-color@8.1.1_/node_modules/@storybook/addon-docs/dist/shims/mdx-react-shim.mjs"(__unused_webpack_module,__webpack_exports__,__webpack_require__){"use strict";__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{MDXProvider:()=>_mdx_js_react__WEBPACK_IMPORTED_MODULE_0__.MDXProvider,useMDXComponents:()=>_mdx_js_react__WEBPACK_IMPORTED_MODULE_0__.useMDXComponents});var _mdx_js_react__WEBPACK_IMPORTED_MODULE_0__=__webpack_require__("./node_modules/.pnpm/@mdx-js+react@3.1.1_@types+react@18.3.3_react@19.2.7/node_modules/@mdx-js/react/index.js")},"./node_modules/.pnpm/@storybook+blocks@8.6.18_react-dom@19.2.7_react@19.2.7__react@19.2.7_storybook@8.6.18_p_8f9138463b79afe28a3a362748d078e4/node_modules/@storybook/blocks/dist sync recursive"(module){function webpackEmptyContext(req){var e=new Error("Cannot find module '"+req+"'");throw e.code="MODULE_NOT_FOUND",e}webpackEmptyContext.keys=()=>[],webpackEmptyContext.resolve=webpackEmptyContext,webpackEmptyContext.id="./node_modules/.pnpm/@storybook+blocks@8.6.18_react-dom@19.2.7_react@19.2.7__react@19.2.7_storybook@8.6.18_p_8f9138463b79afe28a3a362748d078e4/node_modules/@storybook/blocks/dist sync recursive",module.exports=webpackEmptyContext},"./node_modules/.pnpm/@storybook+core@8.6.18_prettier@3.2.5_storybook@8.6.18_prettier@3.2.5_supports-color@8.1.1__supports-color@8.1.1/node_modules/@storybook/core/dist/components sync recursive"(module){function webpackEmptyContext(req){var e=new Error("Cannot find module '"+req+"'");throw e.code="MODULE_NOT_FOUND",e}webpackEmptyContext.keys=()=>[],webpackEmptyContext.resolve=webpackEmptyContext,webpackEmptyContext.id="./node_modules/.pnpm/@storybook+core@8.6.18_prettier@3.2.5_storybook@8.6.18_prettier@3.2.5_supports-color@8.1.1__supports-color@8.1.1/node_modules/@storybook/core/dist/components sync recursive",module.exports=webpackEmptyContext},"./node_modules/.pnpm/@storybook+core@8.6.18_prettier@3.2.5_storybook@8.6.18_prettier@3.2.5_supports-color@8.1.1__supports-color@8.1.1/node_modules/@storybook/core/dist/theming sync recursive"(module){function webpackEmptyContext(req){var e=new Error("Cannot find module '"+req+"'");throw e.code="MODULE_NOT_FOUND",e}webpackEmptyContext.keys=()=>[],webpackEmptyContext.resolve=webpackEmptyContext,webpackEmptyContext.id="./node_modules/.pnpm/@storybook+core@8.6.18_prettier@3.2.5_storybook@8.6.18_prettier@3.2.5_supports-color@8.1.1__supports-color@8.1.1/node_modules/@storybook/core/dist/theming sync recursive",module.exports=webpackEmptyContext},"./packages/nightingale-new-core/src/mixins/withDimensions/README.md"(module){"use strict";module.exports="### withDimensions\n\nIt adds `width` and `height` as parameters.\n\n##### Options\n\nWhen instancing this mixin, the function can receive an object with options for default values:\n\n```javascript\n{\n  width?: number;\n  height?: number;\n}\n```\n\n##### Attributes\n\n###### `height: number (default undefined)`\n\nThe height of the track as a numeric value in pixels.\n\n###### `width: number (default undefined)`\n\nThe width of the track as a numeric value in pixels.\n"},"./packages/nightingale-new-core/src/mixins/withHighlight/README.md"(module){"use strict";module.exports="### withHighlight\n\nIt adds the necessary properties to a component that is using highlight. Notice, this doesn't render the anything in your component. Rather it takes care of setting the parameters and react when they changes.\n\nA component that wants to render a highlight needs to implement the `updateHighlight` method which will be called when the highlight attribute is updated.\n\nIt adds `highlight` and `highlight-color` as attributes.\n\n##### Attributes\n\n###### `highlight: string | null (default null)`\n\nA string representing a set of regions that required to be highilghted. it is a comma separated list of regions and each region, has start and end separated by `:`.\n\nFor example, `1:5,10:20` represents 2 regions. The first region goes from position `1` to `5`, and the second region goes from `10` to `20`.\n\n`null` represents no region needs to be highlighted.\n\n###### `highlight-color: string (default #FFEB3B66)`\n\nThe color to use when rendering the highlight. It follows the web standard defined in https://developer.mozilla.org/en-US/docs/Web/CSS/color_value\n\n##### Properties\n\n###### `fixedHighlight: string | null (default null)`\n\nWorks similar to the `highlight` attribute. The idea is to have a way to define a region that is always highlighted independently of the changes of `highlight`. Used in interpro to highlight the coverage of a chain in a protein.\n\n##### Methods\n\n###### ` protected updateHighlight()`\n\nThis method is called when any the highlight regions changed. In this mixin is just a place holder, but a component using `withHighlight` is expected to implement the highlight rendering logic by overwriting this method.\n"},"./packages/nightingale-new-core/src/mixins/withManager/README.md"(module){"use strict";module.exports="### withManager\n\nAdds the property `manager` which is set in `connectedCallback` as the closest `nigthingale-manager` element, and then it register the component in the manager.\n\n##### Properties\n\n###### `manager?: HTMLElement | null;`\n\nReference to the closest `nighhtingale-manager` component.\n"},"./packages/nightingale-new-core/src/mixins/withMargin/README.md"(module){"use strict";module.exports="### withMargin\n\nDefines attributes for the margin of the component. it has a helper method to render the margins on a given d3 selection; this method is not automatically called, and it's the component resposability to invoke it at the right time.\n\n##### Mixins\n\nImplements the mixin `withDimensions` to be able to calculate values with `width` and `height`.\n\n##### Attributes\n\n###### `margin-top: number (default: 0)`\n\nTop margin in pixels\n\n###### `margin-bottom: number (default: 0)`\n\nBottom margin in pixels\n\n###### `margin-left: number (default: 10)`\n\nLeft margin in pixels\n\n###### `margin-right: number (default: 10)`\n\nRight margin in pixels\n\n###### `margin-color?: string | null (default: #FFFFFFDD)`\n\nThe color to use when rendering the margin. It follows the web standard defined in https://developer.mozilla.org/en-US/docs/Web/CSS/color_value\n\n##### Methods\n\n###### `getWidthWithMargins(): number`\n\nSubstract the defined margins(left and right) from the width.\n\n###### `getHeightWithMargins()`\n\nSubstract the defined margins(top and bottom) from the height.\n\n###### `renderMarginOnGroup( g?: Selection<SVGGElement, unknown, HTMLElement | SVGElement | null, unknown>): void`\n\nGiven a D3 selection it renders rectangles in the position of the margins, filling them with `margin-color`\n"},"./packages/nightingale-new-core/src/mixins/withPosition/README.md"(module){"use strict";module.exports="### withPosition\n\nAdds the attributes required for the position to locate the track.\n\n##### Attributes\n\n###### `display-start?: number (default 1)`\n\nPosition on the sequence where the track should start rendering from.\n\n###### `display-end?: number (default -1)`\n\nPosition on the sequence where the track should end its rendering. The default `-1` represents the end of the sequence.\n\n###### `length?: number (default 0)`\n\nLength of the sequence\n"},"./packages/nightingale-new-core/src/mixins/withResizable/README.md"(module){"use strict";module.exports="### withResizable\n\nUses a `ResizeObserver` to detect changes in the size of the component, and sets the `width` and `height` propertes.\n\n##### Attributes\n\n###### `min-height: number (default 10)`\n\nThe minimum height of the track as a numeric value in pixels.\n\n###### `min-width: number (default 10)`\n\nThe minimum width of the track as a numeric value in pixels.\n\n##### Methods\n\n###### ` protected onDimensionsChange(): void`\n\nOverride this method if there is anything to be done when the dimensions change after the component is resized.\n\n##### Mixins\n\nImplements the mixin `withDimensions` to be able to set the values of `width` and `height` of the component.\n"},"./packages/nightingale-new-core/src/mixins/withZoom/README.md"(module){"use strict";module.exports="### withZoom\n\nAdds the zoom capabilities to a track. It creates a D3 scale between the sequence coordinates (from 1 to the length of the sequence) and the space on screen( from 0 to the width of the component).\n\nThe scale get updated either by a zoom event over the component, or by a change on the attributes: `display-start` or `display-end`.\n\nOnce the scale gets updated the `super.render()` method is invoked triggering a rerender in your component.\n\n##### Mixins\n\nImplements the following mixins:\n\n- `withDimensions` to be able to calculate values with `width` and `height`.\n- `withMargin` to consider the lost margin space in the margins\n- `withPosition` to re calculate the scale whe displayed coordinates(i.e. `display-start` and `display-end`) change.\n\n##### Properties\n\n###### `xScale?: ScaleLinear<number, number>;`\n\nThe scale function for the X axis where on the initial state, the domain goes from `1` to the lenght of the sequence, and the range goes from `0` to the width of the SVG component.\n\nThe domain gets updated when the zoom and panning levels change.\n\nThe range gets updated when the width is changed.\n\n###### `svg?: Selection< SVGSVGElement, unknown, HTMLElement | SVGElement | null, unknown >`;\n\nThe D3 selection to the root `svg` element rendered in the component. The zooming events will be bind to this element.\n\n##### Methods\n\n###### `getSingleBaseWidth(): number`\n\nUses the current scale to calculate the width of a single base on the sequence.\n\n###### `getXFromSeqPosition(position: number): number`\n\nGets the coordinates in the SVG for a given position in the sequence\n\n###### `getSeqPositionFromX(position: number): number`\n\nInverse to `getXFromSeqPosition`\n\n###### `updateScaleDomain(): void`\n\nCall this method to trigger an update on the scale. This only will have an effect if `length`, `width` or `margin-*` have been modified manually.\n\n##### Mixins\n\nImplements the mixins: `withMargin`, `withPosition`, `withResizable`, and `withDimensions`\n"},"./packages/nightingale-new-core/src/nightingale-base-element.md"(module){"use strict";module.exports="### NightingaleElement\n\nThe base element for any Nightingale component. Inherits from [LitElement](https://lit.dev/docs/api/LitElement/).\n\nAny logic that should be shared for all the components should be included here. Currently the only thing is doing, is setting the render root of the components in the element itself, instead of shadowDOM, the Lit element default.\n"}}]);
